<script lang="ts">
 import { resolve } from '$app/paths';
 import { page } from '$app/state';
 import { goto } from '$app/navigation';
 import Seo from '$lib/components/Seo.svelte';
 import { catalogueCollections, catalogueCategories, catalogueFolderUrl } from '$lib/data/catalogues';
 let search = $state('');
 let status = $state('downloadable');
 let sort = $state('name');
 let format = $state('All');
 let visible = $state(18);
 const category = $derived(catalogueCategories.includes(page.url.searchParams.get('category') ?? '') ? page.url.searchParams.get('category')! : 'All');
 const filtered = $derived(catalogueCollections.filter(file => (category === 'All' || file.category === category) && (status === 'all' || file.status === status) && (format === 'All' || file.format === format) && (file.sources.map(source => source.name).join(' ') + ' ' + file.category).toLowerCase().includes(search.trim().toLowerCase())).toSorted((a,b) => sort === 'size' ? a.sizeMB - b.sizeMB : a.displayName.localeCompare(b.displayName)));
 function reset() { search = ''; status = 'downloadable'; sort = 'name'; format = 'All'; visible = 18; goto(resolve('/catalogues'), { noScroll: true, keepFocus: true }); }
</script>
<Seo title="Corporate Gift Catalogues | OfNeeds" description="Search corporate gifting catalogues by category, file type and size. Preview supplier collections in Google Drive or request a replacement copy." crumb="Catalogues" />
<section class="discovery-intro"><div class="container"><p class="eyebrow">Your next idea starts here</p><h1>The OfNeeds<br />Catalogue Library.</h1><p>Browse collections, compare ideas and bring your product references into one clear brief.</p><div class="catalogue-intro-actions"><a class="text-link" href={resolve("/contact#quote")}>Request a curated selection →</a><a class="text-link" href={catalogueFolderUrl} target="_blank" rel="external noopener noreferrer">View shared Drive folder ↗</a></div></div></section>
<section class="section catalogue-library"><div class="container"><h2>Find your collection</h2>
 <div class="discovery-toolbar catalogue-controls"><label for="catalogue-search">Search catalogues<input id="catalogue-search" type="search" bind:value={search} oninput={() => visible = 18} placeholder="Try bottles, Puma or notebooks" /></label><label for="catalogue-status">Source status<select id="catalogue-status" bind:value={status} onchange={() => visible = 18}><option value="downloadable">Download links available</option><option value="request-copy">Request a copy</option><option value="all">All source records</option></select></label><label for="catalogue-sort">Sort by<select id="catalogue-sort" bind:value={sort}><option value="name">Name A–Z</option><option value="size">Smallest file first</option></select></label><label for="catalogue-format">File type<select id="catalogue-format" bind:value={format} onchange={() => visible = 18}><option>All</option><option>PDF</option><option>PPTX</option></select></label></div>
 <nav class="catalogue-filters" aria-label="Catalogue categories">{#each catalogueCategories as item (item)}<a href={resolve((item === 'All' ? '/catalogues' : '/catalogues?category=' + encodeURIComponent(item)) as `/${string}`)} onclick={() => visible = 18} class:selected={category === item} aria-current={category === item ? 'page' : undefined}>{item}</a>{/each}</nav>
 <div class="results-heading"><p aria-live="polite">{filtered.length} collections · {filtered.reduce((count, file) => count + file.sources.length, 0)} source files</p><button type="button" class="text-button" onclick={reset}>Clear all filters</button></div><p class="fineprint">Source metadata last checked 5 October 2026. Google Drive controls current access; the editions shown are not a guarantee of current stock or pricing.</p>
 <div class="catalogue-grid">{#each filtered.slice(0, visible) as file (file.id)}<article class="catalogue-card">
  <div class="catalogue-cover">{#if file.hasCover}<img src={file.image} alt={file.alt} width={file.width} height={file.height} loading="lazy" decoding="async" />{:else}<div class="catalogue-placeholder"><span aria-hidden="true">↗</span><strong>{file.format} collection</strong><small>Cover preview unavailable</small></div>{/if}</div>
  <div class="catalogue-info"><p class="catalogue-meta">{file.category} · {file.format} · {file.size || 'Size not recorded'}</p><h3>{file.displayName}</h3>{#if file.sizeMB >= 50}<p class="large-file">Large file · {file.size}. Prefer Wi-Fi or request a smaller copy.</p>{/if}
   {#if !file.available}<p class="catalogue-status">A downloadable copy was unavailable during our last check. Ask our team for a current copy.</p><a class="text-link" href={resolve(('/contact?catalogue=' + encodeURIComponent(file.displayName) + '#quote') as `/${string}`)}>Request catalogue →</a>
   {:else if file.possibleDuplicate}<p class="catalogue-status">Similar source copies grouped together. Complete contents and latest edition need confirmation.</p><details><summary>Compare {file.sources.length} source copies</summary>{#each file.sources as source (source.id)}<div class="catalogue-source"><p>{source.sourceName}</p><a href={source.preview} target="_blank" rel="external noopener noreferrer">Preview in Drive ↗</a><a data-catalogue-id={source.id} href={source.download} target="_blank" rel="external noopener noreferrer">Download ({source.size}) ↓</a></div>{/each}</details>
   {:else}<div class="catalogue-actions"><a href={file.preview} target="_blank" rel="external noopener noreferrer" aria-label={'Preview ' + file.displayName + ' in Google Drive (new tab)'}>Preview ↗</a><a data-catalogue-id={file.id} href={file.download} target="_blank" rel="external noopener noreferrer" aria-label={'Download ' + file.displayName + ' from Google Drive'}>Download ↓</a></div>{/if}
   <details class="source-details"><summary>Source information</summary><p>{file.sourceName}</p>{#if file.edition}<p>Year in filename: {file.edition}; latest edition unverified.</p>{/if}<p>Last recorded source check: 5 October 2026.</p></details>
  </div></article>{:else}<div class="empty-state"><h3>No matching catalogues</h3><p>Try a broader search or reset the category, status and file-type filters.</p><button type="button" class="button" onclick={reset}>Show all downloadable collections</button></div>{/each}</div>
 {#if filtered.length > visible}<div class="load-more"><button class="button button-outline" type="button" onclick={() => visible += 18}>Show more collections ({Math.min(18, filtered.length - visible)})</button><p class="fineprint">Showing {Math.min(visible, filtered.length)} of {filtered.length} collections</p></div>{/if}
 <p class="catalogue-note">All original supplier records are retained. Five possible duplicate pairs are grouped without choosing a latest edition. Seven historical empty sources appear under “Request a copy”. If Drive asks for access or a download fails, request the catalogue from OfNeeds.</p><div class="catalogue-cta"><div><h2>Found something you like?</h2><p>Include the catalogue title and product code in your brief.</p></div><a class="button" href={resolve("/contact#quote")}>Request a Quote →</a></div>
</div></section>
<style>
 .catalogue-intro-actions { display:flex; flex-wrap:wrap; gap:16px 28px; }.catalogue-controls { margin-top:28px; grid-template-columns:1.4fr 1fr 1fr .65fr; }.catalogue-filters { display:flex; flex-wrap:wrap; gap:8px; margin-block:24px; }.catalogue-filters a { padding:11px 15px; min-height:44px; border:1px solid var(--line); border-radius:30px; font-size:12px; }.catalogue-filters a.selected { color:white; background:var(--navy); border-color:var(--navy); }
 .catalogue-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:24px; }.catalogue-card { border:1px solid var(--line); border-radius:12px; overflow:hidden; background:white; min-width:0; }.catalogue-cover { background:#f3f6f7; }.catalogue-cover img { width:100%; height:260px; object-fit:contain; padding:18px; }.catalogue-placeholder { height:260px; display:grid; place-content:center; gap:16px; text-align:center; color:var(--blue); }.catalogue-placeholder > span { font-size:45px; }.catalogue-placeholder small { color:var(--muted); font-size:11px; }.catalogue-info { padding:22px; }.catalogue-meta { font-size:10px; color:var(--blue); margin-bottom:12px; }.catalogue-info h3 { font-size:17px; line-height:1.4; margin-bottom:18px; overflow-wrap:anywhere; }.catalogue-actions { display:flex; justify-content:space-between; gap:18px; border-top:1px solid var(--line); padding-top:16px; font-size:12px; font-weight:650; }.catalogue-actions a { min-height:36px; display:flex; align-items:center; }.catalogue-status,.large-file { font-size:12px; line-height:1.7; }.large-file { padding:10px; color:#70520e; background:#fff7e8; border-radius:5px; }.source-details { margin-top:16px; }.catalogue-info summary { font-size:11px; min-height:36px; padding-block:10px; }.catalogue-info details p { font-size:11px; overflow-wrap:anywhere; margin-block:10px; }.catalogue-source { padding-block:10px; border-bottom:1px solid var(--line); }.catalogue-source a { display:block; font-size:12px; padding-block:8px; text-decoration:underline; }.catalogue-note { font-size:12px; max-width:850px; margin:30px 0; }.catalogue-cta { display:flex; justify-content:space-between; align-items:center; gap:24px; margin-top:45px; padding:32px; background:#eef4f6; border-radius:12px; }.catalogue-cta h2 { font-size:26px; margin-bottom:12px; }.catalogue-cta p { margin:0; }.load-more { text-align:center; margin-top:30px; }.load-more p { margin-top:12px; }
 @media(max-width:1000px) { .catalogue-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }.catalogue-controls { grid-template-columns:1fr 1fr; } }
 @media(max-width:600px) { .catalogue-grid,.catalogue-controls { grid-template-columns:1fr; }.catalogue-cta { flex-direction:column; align-items:start; padding:24px; }.catalogue-filters a { padding:11px 13px; } }
</style>
